//! Low-frequency oscillator with sine and triangle shapes.
//!
//! The LFO has its own phase, independent from the audio oscillator. It outputs
//! a bipolar signal in `[-1, 1]`; the voice maps that signal to cutoff octaves
//! or pitch semitones. It is advanced once per block by the voice, which
//! interpolates the resulting modulation across the block.

use std::f64::consts::TAU;

/// Lowest LFO rate, in hertz.
pub const MIN_RATE_HZ: f32 = 0.01;
/// Highest LFO rate, in hertz.
pub const MAX_RATE_HZ: f32 = 20.0;

/// Shape generated by the LFO.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LfoWaveform {
    /// Smooth sinusoidal shape.
    Sine,
    /// Piecewise-linear triangular shape.
    Triangle,
}

/// Low-frequency oscillator with an independent `f64` phase.
#[derive(Clone, Debug)]
pub struct Lfo {
    sample_rate_hz: f32,
    rate_hz: f32,
    waveform: LfoWaveform,
    phase: f64,
}

impl Lfo {
    /// Creates a 0.5 Hz sine LFO at 48 kHz.
    pub fn new(sample_rate_hz: f32) -> Self {
        let mut lfo = Self {
            sample_rate_hz: 48_000.0,
            rate_hz: 0.5,
            waveform: LfoWaveform::Sine,
            phase: 0.0,
        };
        lfo.prepare(sample_rate_hz);
        lfo
    }

    /// Prepares the LFO for a sample rate and resets the phase.
    pub fn prepare(&mut self, sample_rate_hz: f32) {
        self.sample_rate_hz = if sample_rate_hz.is_finite() && sample_rate_hz > 0.0 {
            sample_rate_hz
        } else {
            48_000.0
        };
        self.phase = 0.0;
    }

    /// Sets the rate in hertz, clamped to the accepted range.
    pub fn set_rate_hz(&mut self, rate_hz: f32) {
        if rate_hz.is_finite() {
            self.rate_hz = rate_hz.clamp(MIN_RATE_HZ, MAX_RATE_HZ);
        }
    }

    /// Sets the waveform.
    pub fn set_waveform(&mut self, waveform: LfoWaveform) {
        self.waveform = waveform;
    }

    /// Returns the current rate in hertz.
    pub const fn rate_hz(&self) -> f32 {
        self.rate_hz
    }

    /// Returns the current waveform.
    pub const fn waveform(&self) -> LfoWaveform {
        self.waveform
    }

    /// Returns the normalised phase.
    pub const fn phase(&self) -> f64 {
        self.phase
    }

    /// Resets the phase to zero.
    pub fn reset(&mut self) {
        self.phase = 0.0;
    }

    /// Returns the current bipolar value in `[-1, 1]`.
    pub fn value(&self) -> f32 {
        let value = match self.waveform {
            LfoWaveform::Sine => (TAU * self.phase).sin(),
            // +1 at phase 0, -1 at phase 0.5, +1 at phase 1.
            LfoWaveform::Triangle => 4.0 * (self.phase - 0.5).abs() - 1.0,
        };

        if value.is_finite() {
            (value as f32).clamp(-1.0, 1.0)
        } else {
            0.0
        }
    }

    /// Advances the phase by `frames` samples.
    pub fn advance(&mut self, frames: usize) {
        let increment = f64::from(self.rate_hz) * frames as f64 / f64::from(self.sample_rate_hz);
        if increment.is_finite() {
            self.phase = (self.phase + increment).rem_euclid(1.0);
        }
    }
}

impl Default for Lfo {
    fn default() -> Self {
        Self::new(48_000.0)
    }
}

#[cfg(test)]
mod tests {
    #![allow(clippy::float_cmp)]

    use super::{Lfo, LfoWaveform, MAX_RATE_HZ, MIN_RATE_HZ};

    const SAMPLE_RATE_HZ: f32 = 48_000.0;

    fn render(rate_hz: f32, waveform: LfoWaveform, frames: usize) -> Vec<f32> {
        let mut lfo = Lfo::new(SAMPLE_RATE_HZ);
        lfo.set_rate_hz(rate_hz);
        lfo.set_waveform(waveform);

        (0..frames)
            .map(|_| {
                let value = lfo.value();
                lfo.advance(1);
                value
            })
            .collect()
    }

    fn measure_frequency_hz(samples: &[f32], sample_rate_hz: f32) -> f32 {
        let mut crossings = 0_usize;
        let mut first = 0.0_f64;
        let mut last = 0.0_f64;

        for index in 1..samples.len() {
            let previous = samples[index - 1];
            let current = samples[index];
            if previous <= 0.0 && current > 0.0 {
                let denominator = f64::from(current - previous);
                let fraction = if denominator == 0.0 {
                    0.0
                } else {
                    -f64::from(previous) / denominator
                };
                let position = (index - 1) as f64 + fraction;
                if crossings == 0 {
                    first = position;
                }
                last = position;
                crossings += 1;
            }
        }

        if crossings < 2 {
            return 0.0;
        }
        let cycles = (crossings - 1) as f64;
        (cycles * f64::from(sample_rate_hz) / (last - first)) as f32
    }

    #[test]
    fn sine_frequency_is_accurate() {
        for rate_hz in [0.5_f32, 5.0, 20.0] {
            let samples = render(rate_hz, LfoWaveform::Sine, 48_000 * 5);
            let measured = measure_frequency_hz(&samples, SAMPLE_RATE_HZ);
            let relative_error = (measured - rate_hz).abs() / rate_hz;
            assert!(
                relative_error < 0.001,
                "{rate_hz} Hz measured {measured} Hz"
            );
        }
    }

    #[test]
    fn triangle_frequency_is_accurate() {
        let rate_hz = 5.0;
        let samples = render(rate_hz, LfoWaveform::Triangle, 48_000 * 5);
        let measured = measure_frequency_hz(&samples, SAMPLE_RATE_HZ);
        let relative_error = (measured - rate_hz).abs() / rate_hz;
        assert!(
            relative_error < 0.001,
            "{rate_hz} Hz measured {measured} Hz"
        );
    }

    #[test]
    fn output_stays_bipolar_and_bounded() {
        for waveform in [LfoWaveform::Sine, LfoWaveform::Triangle] {
            let samples = render(20.0, waveform, 48_000);
            assert!(samples.iter().all(|sample| (-1.0..=1.0).contains(sample)));
            assert!(samples.iter().any(|sample| *sample > 0.9));
            assert!(samples.iter().any(|sample| *sample < -0.9));
        }
    }

    #[test]
    fn triangle_shape_hits_the_expected_points() {
        let mut lfo = Lfo::new(SAMPLE_RATE_HZ);
        lfo.set_waveform(LfoWaveform::Triangle);
        assert_eq!(lfo.value(), 1.0);

        lfo.advance(48_000);
        assert!((lfo.value() + 1.0).abs() < 1e-5);
    }

    #[test]
    fn rate_is_clamped_and_invalid_values_keep_the_previous_rate() {
        let mut lfo = Lfo::new(SAMPLE_RATE_HZ);
        lfo.set_rate_hz(100.0);
        assert_eq!(lfo.rate_hz(), MAX_RATE_HZ);
        lfo.set_rate_hz(0.0);
        assert_eq!(lfo.rate_hz(), MIN_RATE_HZ);
        lfo.set_rate_hz(3.0);
        lfo.set_rate_hz(f32::NAN);
        assert_eq!(lfo.rate_hz(), 3.0);
    }
}
